# Search for grid data in the session file - it's JSONL but grids might be in tool output
import os
import json

d = os.environ['RLM_SESSION_DIR']
session_name = os.path.basename(d)
target_path = d + '/../../sessions/' + session_name + '.jsonl'

with open(target_path, 'r') as f:
    content = f.read()

# Parse as JSONL and look for grid content
lines = content.split('\n')
demo_grids = {}

for line in lines:
    if line.strip():
        try:
            entry = json.loads(line)
            # Check if it has tool output or user message with grid data
            if 'tool' in entry:
                tool_result = entry.get('role', '')
                if tool_result == 'toolResult':
                    # Find all text items in the tool result
                    for item in entry.get('content', []):
